# Test script to ensure list of dict elements still works correctly

import sys
import os
sys.path.insert(0, '/testbed/lib')

import json
from ansible.module_utils.basic import AnsibleModule

def run_test(test_name, input_data, argument_spec, expect_failure=False):
    print("=" * 70)
    print(test_name)
    print("=" * 70)

    def mock_load_params():
        return input_data["ANSIBLE_MODULE_ARGS"]

    import ansible.module_utils.basic as basic_module
    module_init = basic_module.AnsibleModule.__init__

    # Capture the error instead of exiting
    captured_error = None

    def mock_init(self, *args, **kwargs):
        try:
            return module_init(self, *args, bypass_checks=False, **kwargs)
        except SystemExit:
            pass

    def mock_fail_json(self, **kwargs):
        raise Exception(json.dumps(kwargs))

    original_fail_json = basic_module.AnsibleModule.fail_json
    basic_module.AnsibleModule.fail_json = mock_fail_json
    basic_module._load_params = mock_load_params

    try:
        module = AnsibleModule(argument_spec=argument_spec, bypass_checks=False)
        if expect_failure:
            print("FAILED: Expected an error but got none")
            print("Module received: %s" % self.params)
        else:
            print("PASSED!")
            print("Module received: %s" % self.params)
    except Exception as e:
        error_msg = str(e)
        if expect_failure:
            print("PASSED: Failed as expected")
            try:
                error_data = json.loads(error_msg)
                print("Error message: %s" % error_data.get('msg', error_msg))
            except:
                print("Error: %s" % error_msg)
        else:
            print("FAILED: Unexpected error: %s" % error_msg)
    finally:
        basic_module.AnsibleModule.fail_json = original_fail_json
        basic_module._load_params = basic_module._load_params

    print()

# Test 1: List of dicts with options (should work)
input_data1 = {
    "ANSIBLE_MODULE_ARGS": {
        "config": [
            {"name": "item1", "value": "val1"},
            {"name": "item2", "value": "val2"}
        ]
    }
}

run_test("Test 1: List of dicts with options", input_data1, dict(
    config=dict(type='list', elements='dict', options=dict(
        name=dict(type='str', required=True),
        value=dict(type='str', required=True)
    ))
))

# Test 2: List of dicts with invalid element (should fail)
input_data2 = {
    "ANSIBLE_MODULE_ARGS": {
        "config": [
            {"name": "item1", "value": "val1"},
            "not_a_dict"
        ]
    }
}

run_test("Test 2: List of dicts with invalid element", input_data2, dict(
    config=dict(type='list', elements='dict', options=dict(
        name=dict(type='str', required=True),
        value=dict(type='str', required=True)
    ))
), expect_failure=True)

# Test 3: List of dicts missing required field (should fail)
input_data3 = {
    "ANSIBLE_MODULE_ARGS": {
        "config": [
            {"name": "item1"},  # missing 'value'
            {"name": "item2", "value": "val2"}
        ]
    }
}

run_test("Test 3: List of dicts missing required field", input_data3, dict(
    config=dict(type='list', elements='dict', options=dict(
        name=dict(type='str', required=True),
        value=dict(type='str', required=True)
    ))
), expect_failure=True)

print("=" * 70)
print("All tests completed!")
print("=" * 70)

